def eval_task(self, agent_responses: List[str]) -> Tuple[bool, Dict[str, Any]]:
    emails = get_emails_by_customer_id("CUST1125")
    bodies = " ".join((e.get("body") or "") for e in emails)
    if not emails:
        return False, {"message": "No email records for CUST1125; expected a credit email"}
    if "credit" in bodies.lower() and "$" in bodies:
        return True, {"message": "Found service credit email for CUST1125"}
    return False, {"message": "Expected email mentioning credit and amount for CUST1125", "email_bodies": bodies}
